import {VERIFIED,REPO,sources,places,events,articles,board,categories} from './data.js';

const paths={arrow:'M4 12h16m-6-6 6 6-6 6',leaf:'M20 3c-12-1-18 5-14 12 6 8 15 1 14-12ZM5 21 16 10M10 16v-5m3 2h5',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',pencil:'m4 16-1 5 5-1L21 7l-4-4L4 16Zm10-10 4 4M4 16l4 4',home:'m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',spark:'m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2Z',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bookmark:'M6 3h12v18l-6-4-6 4V3Z',pin:'M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 0 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',calendar:'M4 5h16v16H4V5ZM7 3v4m10-4v4M4 10h16m-12 4h2m4 0h2m-8 3h2',menu:'M4 6h16M4 12h16M4 18h16',close:'m5 5 14 14M5 19 19 5',external:'M14 3h7v7m0-7L10 14M10 5H4v15h15v-7',check:'m5 12 4 4L19 6',theatre:'M3 4c4 2 7 2 11 0v8c0 4-6 7-6 7s-5-3-5-7V4Zm3 5h1m3 0h1M6 13q2 2 4 0M15 9l6-1v7c0 4-5 6-5 6',music:'M9 18V5l11-2v13M9 8l11-2M9 18c0 2-6 3-6 0s6-3 6 0Zm11-2c0 2-6 3-6 0s6-3 6 0',art:'M3 5h18v15H3V5Zm3 11 4-4 3 3 3-6 3 7M8 9h.01',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6v-7Zm11-2h1',rss:'M4 11a9 9 0 0 1 9 9M4 4a16 16 0 0 1 16 16M6 19a1 1 0 1 1-2 0 1 1 0 0 1 2 0'};
export const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
export const escape=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ext=(url)=>`href="${escape(url)}" target="_blank" rel="noopener noreferrer"`;
const articleURL=id=>`articles/${id}/`;
const nowISO=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Skopje',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const addDays=(date,n)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
export function eventMatches(e,range,today=nowISO()){if(range==='archive')return e.end<today;if(e.end<today)return false;if(range==='today')return e.start<=today;if(range==='weekend'){const day=new Date(today+'T12:00:00Z').getUTCDay();const sat=addDays(today,day===0?-1:(6-day));return e.start<=addDays(sat,1)&&e.end>=sat;}if(range==='month')return e.start<=today.slice(0,7)+'-31';return true;}
const monthNames=['јануари','февруари','март','април','мај','јуни','јули','август','септември','октомври','ноември','декември'];
const dateMK=s=>`${Number(s.slice(8))} ${monthNames[Number(s.slice(5,7))-1]} ${s.slice(0,4)}`;
let saved=[];let storageAvailable=true;
if(typeof window!=='undefined'){try{const raw=JSON.parse(localStorage.getItem('kroshna-plan-v1')||'[]');if(Array.isArray(raw))saved=raw.filter(x=>typeof x==='string').slice(0,200);}catch{storageAvailable=false;}}
const isSaved=(key)=>saved.includes(key);
const saveButton=(type,id)=>`<button class="save" data-save="${type}:${id}" aria-label="${isSaved(type+':'+id)?'Отстрани од':'Зачувај во'} мојот план" aria-pressed="${isSaved(type+':'+id)}">${icon('bookmark')}</button>`;
const brand=()=>`<a class="brand" href="./" aria-label="крошна — почетна"><img src="assets/mark.svg" alt="" width="35" height="42"><span><span class="wordmark">крошна</span><small>РАСТЕМЕ ЗАЕДНО</small></span></a>`;
const art=(name)=>`<div class="art-panel ${escape(name)}">${icon(name)}</div>`;
const imageHTML=(p,cls='')=>p.image?`<img class="${cls}" src="assets/${p.image}.webp" alt="${p.illustrative?'Фотографија од околината · ':''}${escape(p.image==='park'?'Градски парк, Скопје':p.image==='matka'?'Кањон Матка':'Музеј на современата уметност, Скопје')}" width="1280" height="850" loading="lazy">`:art(p.art||'spark');
const linkArrow=(text,url)=>`<a class="text-link" href="${url}">${text}${icon('arrow')}</a>`;
const breadcrumb=(name)=>`<div class="breadcrumb"><a href="./">Дома</a><span>/</span><span>${escape(name)}</span></div>`;
const pageHero=(label,title,desc)=>`<div class="page-hero">${breadcrumb(label)}<div class="eyebrow">${label}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
const journalCover=()=>`<div class="journal-cover-scene" aria-label="Концепт за првиот број на печатениот журнал"><div class="journal-cover"><div><div class="wordmark">крошна</div><div class="journal-cover-top"><span>НЕЗАВИСЕН СЕМЕЕН ЖУРНАЛ</span><span>БР. 00 / 2026</span></div></div><img class="cover-tree" src="assets/mark.svg" alt="" width="125" height="143"><div><div class="journal-cover-bottom">Мали денови.<br>Големи спомени.</div><div class="cover-caption">СКОПЈЕ · ЕСЕН 2026 · ПИЛОТ ИЗДАНИЕ</div></div></div><div class="journal-sticker hand">За чување.<br>И за нас.</div></div>`;

export function renderHeader(active='home'){
 const nav=[['explore','Истражи'],['events','Настани'],['stories','Приказни'],['board','Одбор'],['journal','Журнал']];
 return `<div class="topline">Еден град. Многу мали светови.<span>✳</span>Твојата семејна крошна во Скопје.</div><div class="site-header"><div class="container header-inner">${brand()}<nav class="nav" aria-label="Главна навигација">${nav.map(([id,title])=>`<a href="./#/${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav><div class="header-tools"><button class="icon-button" data-action="search" aria-label="Пребарај ја крошна">${icon('search')}</button><a class="icon-button" href="./#/plan" aria-label="Мојот план, ${saved.length} зачувани">${icon('bookmark')}<span class="count" ${saved.length?'':'hidden'}>${saved.length}</span></a><button class="button small" data-action="submit">Сподели откритие ${icon('arrow')}</button><button class="icon-button menu-toggle" data-action="menu" aria-expanded="false" aria-controls="mobile-menu" aria-label="Отвори мени">${icon('menu')}</button></div></div><nav class="mobile-nav" id="mobile-menu" hidden aria-label="Мобилна навигација">${nav.map(([id,title])=>`<a href="./#/${id}">${title}</a>`).join('')}<a href="./#/plan">Мојот план</a><a href="./#/about">За крошна</a></nav></div>`;
}
export function renderFooter(){return `<div class="container"><div class="closing"><div><h2>Убавите работи се споделуваат.</h2><p>Знаеш едно убаво место? Или имаш приказна што вреди да се раскаже?</p></div><div class="closing-links"><button class="button outline" data-action="submit">Сподели со крошна ${icon('arrow')}</button><a class="text-link" href="./#/updates">Следи ги приказните ${icon('rss')}</a></div></div><div class="footer-main"><div class="footer-grid"><div>${brand()}<p>Независен водич за мали авантури,<br>добри места и заеднички денови во Скопје.</p></div><div class="footer-col"><strong>ПРОШЕТАЈ НИЗ КРОШНА</strong><a href="./#/explore">Места и мали авантури</a><a href="./#/events">Календар на настани</a><a href="./#/explore?category=support">Центри и поддршка</a><a href="./#/reviews">Уреднички осврти</a></div><div class="footer-col"><strong>ОД НАШАТА ЗАЕДНИЦА</strong><a href="./#/stories">Водичи и приказни</a><a href="./#/board">Курираниот одбор</a><a href="./#/journal">Печатениот журнал</a><a href="./#/plan">Мојот план</a></div><div class="footer-col"><strong>ДА СЕ ЗАПОЗНАЕМЕ</strong><a href="./#/about">Приказната за крошна</a><a href="./#/brand">Визуелен идентитет</a><a href="./#/partners">Рекламирање и соработка</a><a href="./#/standards">Нашите уреднички правила</a></div></div><div class="footer-bottom"><span>© 2026 крошна. Создадено со љубопитност во Скопје.</span><span><a href="./#/privacy">Приватност</a> · <a href="./#/credits">Извори и фотографии</a> · <a ${ext(REPO)}>GitHub ${icon('external')}</a></span></div></div></div>`;}
function miniEvent(e){return `<a class="mini-event" href="./#/events?event=${e.id}"><div class="date-box"><strong>${e.start.slice(8,10)}</strong><span>${monthNames[Number(e.start.slice(5,7))-1].slice(0,3)}</span></div><div><h4>${escape(e.title)}</h4><p>${escape(e.type)} · ${escape(e.area)}<br>до ${dateMK(e.end)}</p></div></a>`;}
function articleCard(a){return `<article class="article-card"><a href="${articleURL(a.id)}" class="article-image" aria-label="Прочитај: ${escape(a.title)}">${imageHTML(a)}</a><div class="article-meta"><span>${a.category}</span><span class="dot"></span><span>${a.read} ЧИТАЊЕ</span></div><h3><a href="${articleURL(a.id)}">${a.title}</a></h3><p>${a.intro}</p><div class="card-bottom"><a href="${articleURL(a.id)}">Прочитај ја приказната ${icon('arrow')}</a>${saveButton('article',a.id)}</div></article>`;}
function boardCard(b){return `<article class="board-note ${b.color||'green'}"><div class="eyebrow">${escape(b.type)}</div><h3 class="hand">${escape(b.title)}</h3><p>${escape(b.text)}</p><a ${ext(b.url)}>${escape(b.source)}${icon('external')}</a></article>`;}
function adBanner(){return `<aside class="ad-banner" aria-label="Демонстрација на рекламен банер"><div><span class="ad-label">РЕКЛАМЕН КОНЦЕПТ · БЕЗ ПАРТНЕРСТВО</span><span class="ad-brand">Литература.мк<span style="color:#a52f54">↗</span></span></div><div><h3>Следната авантура е меѓу кориците.</h3><p>Пример за место за книжен партнер на крошна.</p></div><a href="https://www.literatura.mk/" target="_blank" rel="noopener noreferrer">Истражи книги ↗</a></aside>`;}
export function renderHome(today=nowISO()){
 const current=events.filter(e=>eventMatches(e,'all',today)).sort((a,b)=>a.end.localeCompare(b.end));
 return `<div class="container"><section class="hero"><div class="hero-copy"><div class="hero-pill"><i></i>ЗА МАЛИТЕ И ГОЛЕМИТЕ</div><h1>Градот е<br>поубав кога <span>растеме заедно.</span></h1><p>Мали авантури, убави места и вистински приказни. Твојот семеен водич низ Скопје, со љубов и љубопитност.</p><div class="hero-actions"><a class="button" href="./#/explore">Ајде да истражуваме ${icon('arrow')}</a>${linkArrow('Што има деновиве?','./#/events')}</div><div class="hero-footnote">${icon('heart')}За секое семејство. За секое наше маало.</div></div><div class="hero-art"><img class="hero-photo" src="assets/park.webp" alt="Посетители покрај езерцето во Градскиот парк во Скопје" width="1280" height="960" fetchpriority="high"><img class="hero-sun" src="assets/sun.svg" alt="" width="126" height="126"><a class="hero-note" href="${articleURL('park-bez-plan')}"><span class="hand">Денес, малку надвор.</span><p>Една прошетка. Илјада откритија.</p>${icon('arrow')}</a><div class="photo-caption">Градски парк, Скопје · фото: d*oraz / CC BY-SA 2.0</div></div></section><div class="category-strip" aria-label="Истражи по категорија">${categories.slice(1).concat([{id:'all',name:'Сите наши места',icon:'spark'}]).map(c=>`<a class="category-shortcut" href="./#/explore?category=${c.id}"><span class="category-icon">${icon(c.icon)}</span><span>${c.name}</span></a>`).join('')}</div><section class="section"><div class="section-top"><div><div class="eyebrow">ЕДИТОРСКИ ИЗБОР · ЕСЕН ВО СКОПЈЕ</div><h2>Да го направиме денот убав.</h2></div>${linkArrow('Сите откритија','./#/explore')}</div><div class="home-discover"><a class="feature-card" href="${articleURL('matka-so-deca')}"><img src="assets/matka.webp" alt="Зелената вода и карпите на кањонот Матка" width="1280" height="850" loading="lazy"><div class="feature-content"><span class="tag">МАЛА АВАНТУРА · МАТКА</span><h3>Понекогаш, ни треба<br>само друг хоризонт.</h3><p>Еден семеен ден покрај кањонот. Со детско темпо.</p><div class="feature-bottom"><span>Водич · 5 мин читање</span><span class="circle-arrow">${icon('arrow')}</span></div></div></a><aside class="weekend-card"><div class="weekend-card-header"><h3 class="hand">Деновиве во градот</h3>${icon('calendar')}</div>${current.length?current.slice(0,3).map(miniEvent).join(''):`<div class="source-note">Подготвуваме нов избор. Погледнете ги официјалните програми во календарот.</div>`}${linkArrow('Отвори го календарот','./#/events')}</aside></div>${adBanner()}</section></div><section class="section soft-section home-stories"><div class="container"><div class="section-top"><div><div class="eyebrow">ПРИКАЗНИ ЗА ЧИТАЊЕ И ЖИВЕЕЊЕ</div><h2>Од нашата крошна.</h2></div>${linkArrow('Сите приказни','./#/stories')}</div><div class="cards-grid">${articles.slice(0,3).map(articleCard).join('')}</div></div></section><section class="section"><div class="container"><div class="section-top"><div><div class="eyebrow">ЕДНО МАЛО МЕСТО ЗА ДОБРИ НЕШТА</div><h2>На нашиот одбор.</h2><p>Внимателно одбрани откритија од градот. За да ни бидат при рака.</p></div>${linkArrow('Кон одборот','./#/board')}</div><div class="board-grid">${board.map(boardCard).join('')}</div></div></section><section class="journal-section"><div class="container journal-inner">${journalCover()}<div class="journal-copy"><div class="eyebrow">КРОШНА НА ХАРТИЈА · БРОЈ 00</div><h2>Некои приказни<br>заслужуваат да останат.</h2><p>Го подготвуваме нашиот семеен журнал. Приказни од градот, мали водичи и страници што ќе ги чуваме долго откако ќе пораснеме.</p><a class="button" href="./#/journal">Ѕирни во првиот број ${icon('arrow')}</a><small>Пилот издание за читање и печатење дома. Печатен тираж во подготовка.</small></div></div></section>`;
}
export function filterPlaces({q='',category='all',age='all',area='all'}={}){const normalized=q.toLocaleLowerCase('mk').trim();return places.filter(p=>(category==='all'||p.category===category)&&(area==='all'||p.area===area)&&(age==='all'||(p.age<=({0:2,3:5,6:9,10:99}[age]??Number(age))&&p.ageMax>=Number(age)))&&(!normalized||`${p.title} ${p.description} ${p.area} ${p.address}`.toLocaleLowerCase('mk').includes(normalized)));}
function placeCard(p){return `<article class="place-card"><div class="place-image"><button data-place="${p.id}" style="display:block;width:100%;height:100%;padding:0;background:none" aria-label="Детали за ${escape(p.title)}">${imageHTML(p)}</button>${saveButton('place',p.id)}${p.illustrative?'<span class="image-note">Фотографија од околината</span>':''}</div><div class="place-body"><div class="eyebrow">${p.tag}</div><h3><button class="title-button" data-place="${p.id}">${p.title}</button></h3><p>${p.description}</p><div class="place-meta"><span>${icon('pin')}${p.area}</span><span>${icon('heart')}${p.category==='support'?'Проверете услови':p.age===0?'Сите возрасти':p.age+'+'}</span><span>${p.price}</span></div><div class="card-bottom"><button data-place="${p.id}">Повеќе за местото ${icon('arrow')}</button></div></div></article>`;}
const areas=[...new Set(places.map(p=>p.area))].sort();
export function renderExplore(params=new URLSearchParams()){
 const q=params.get('q')||'',category=params.get('category')||'all',age=params.get('age')||'all',area=params.get('area')||'all',view=params.get('view')||'grid';const found=filterPlaces({q,category,age,area});
 return `<div class="container page-content">${pageHero('ИСТРАЖИ ГО ГРАДОТ','Каде одиме денес?','Од блискиот парк до едно мало бегство. Пронајди место за возраста, маалото и ритамот на твоето семејство.')}<form class="filters" id="explore-form"><div class="filter-row"><label class="search-field"><span class="sr-only">Пребарај места</span>${icon('search')}<input name="q" type="search" placeholder="Место, маало или мала идеја..." value="${escape(q)}" aria-label="Пребарај места"></label><label><span>ВОЗРАСТ</span><select name="age" aria-label="Возраст"><option value="all">Сите возрасти</option>${[[0,'0–2 години'],[3,'3–5 години'],[6,'6–9 години'],[10,'10+ години']].map(([v,t])=>`<option value="${v}" ${age===String(v)?'selected':''}>${t}</option>`).join('')}</select></label><label><span>МААЛО / ОБЛАСТ</span><select name="area" aria-label="Маало"><option value="all">Цело Скопје</option>${areas.map(a=>`<option ${area===a?'selected':''}>${a}</option>`).join('')}</select></label><input name="category" type="hidden" value="${escape(category)}"><input name="view" type="hidden" value="${escape(view)}"><button class="button" type="submit">Пронајди ${icon('arrow')}</button></div><div class="chips">${categories.map(c=>`<button class="chip ${category===c.id?'active':''}" type="button" data-category="${c.id}" aria-pressed="${category===c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div></form><div class="results-bar"><span><strong>${found.length} ${found.length===1?'место':'места'}</strong> за твојот следен убав ден</span><div class="view-switch"><button data-view="grid" class="${view==='grid'?'active':''}" aria-pressed="${view==='grid'}">Листа</button><button data-view="map" class="${view==='map'?'active':''}" aria-pressed="${view==='map'}">Карта</button><a class="chip" href="./#/explore">Исчисти</a></div></div>${view==='map'?`<div class="map-panel"><iframe title="Карта на Скопје — OpenStreetMap" src="https://www.openstreetmap.org/export/embed.html?bbox=21.30%2C41.94%2C21.51%2C42.04&layer=mapnik" loading="lazy" referrerpolicy="no-referrer"></iframe><small>Ориентациска карта на градот · © OpenStreetMap contributors. За точна рута отворете „На карта“ во профилот на избраното место.</small></div>`:''}<div class="cards-grid" id="place-results">${found.length?found.map(placeCard).join(''):emptyState('Нема места за овој избор.','Пробај друго маало, друга возраст или пократок збор.','./#/explore','Покажи ги сите места')}</div><div class="source-note">Јавни извори проверени на 16.10.2026. Возрастите се уреднички предлози, освен каде што е наведено поинаку. Пристапноста и условите за прием проверете ги директно. <a href="./#/standards">Како ги избираме местата</a>.</div></div>`;
}
function emptyState(title,text,url,label){return `<div class="empty-state">${icon('leaf')}<h3>${title}</h3><p>${text}</p><a class="button" href="${url}">${label} ${icon('arrow')}</a></div>`;}
export function renderEvents(params=new URLSearchParams(),today=nowISO()){
 const range=params.get('range')||'all';const selected=events.filter(e=>eventMatches(e,range,today)).sort((a,b)=>a.start.localeCompare(b.start));
 return `<div class="container page-content">${pageHero('КАЛЕНДАР','Мали поводи за големи денови.','Реални настани од објавени програми. Пред тргнување, провери ги условите и точниот термин кај организаторот.')}<div class="board-toolbar"><div class="chips">${[['all','Сите актуелни'],['today','Денес'],['weekend','Овој викенд'],['month','Овој месец'],['archive','Архива']].map(([id,t])=>`<a class="chip ${range===id?'active':''}" href="./#/events?range=${id}" ${range===id?'aria-current="true"':''}>${t}</a>`).join('')}</div><span class="muted" style="font-size:11px">Денес: ${dateMK(today)} · Скопје</span></div><div class="event-list">${selected.length?selected.map(e=>`<article class="event-row"><div class="date-box"><strong>${e.start.slice(8)}</strong><span>${monthNames[Number(e.start.slice(5,7))-1].slice(0,3)}</span></div><div><span class="tag">${e.type} · ${e.age}+*</span><h3><button class="title-button" data-event="${e.id}">${e.title}</button></h3><p>${e.place}</p><p style="font-size:11px;margin-top:7px">${dateMK(e.start)} — ${dateMK(e.end)}</p></div><div class="event-actions"><span class="event-time">${e.time}</span><button class="button small" data-event="${e.id}">Детали ${icon('arrow')}</button><button class="button outline small" data-calendar="${e.id}">${icon('calendar')}Во календар</button>${saveButton('event',e.id)}</div></article>`).join(''):emptyState('Нема потврдени настани во овој период.','Погледни ги актуелните изложби или програмите по договор.','./#/events','Сите актуелни настани')}</div><div class="source-note">* Возраста е предлог на редакцијата, не услов објавен од организаторот. Календарските датотеки се целодневни опсези; тие не се резервација. Завршените настани автоматски преминуваат во архивата.</div><div class="section-top"><div><div class="eyebrow">КОГА САКАТЕ ДА СОЗДАВАТЕ</div><h2>Работилници по договор.</h2><p>Постојани едукативни програми. Термините се договараат директно.</p></div></div><div class="cards-grid">${places.filter(p=>p.category==='workshop').map(placeCard).join('')}</div></div>`;
}
export function renderStories(){return `<div class="container page-content">${pageHero('ВОДИЧИ И ПРИКАЗНИ','За читање. За пробување. За нас.','Оригинални водичи, мали домашни идеи и приказни засновани на јавно објавени факти. Со извори, со простор за љубопитност.')}<div class="cards-grid">${articles.map(articleCard).join('')}</div></div>`;}
export function renderArticle(id){const a=articles.find(a=>a.id===id);if(!a)return render404();return `<div class="container page-content"><article class="article-page"><div class="page-hero">${breadcrumb('Приказни')}<div class="eyebrow">${a.category} · ${a.read} ЧИТАЊЕ</div><h1>${a.title}</h1><p class="article-lead">${a.intro}</p><div class="inline-tags"><span>${a.age} години</span><span>Оригинален уреднички текст</span></div></div>${a.image?imageHTML(a,'article-cover'):art(a.art)}<div class="article-byline"><span>Редакција крошна · 16 октомври 2026</span><span>Зачувај за подоцна</span>${saveButton('article',a.id)}<button class="save no-print" data-action="print" aria-label="Испечати ја приказната">${icon('print')}</button></div><div class="article-body">${a.sections.map(([t,p])=>`<section><h2>${t}</h2><p>${p}</p></section>`).join('')}<div class="article-sources"><h3>${a.sources.length?'Извори и дополнително читање':'Од нашата редакција'}</h3>${a.sources.length?a.sources.map(s=>`<a ${ext(s.url)}>${s.title} ${icon('external')}</a>`).join(''):'Оригинална домашна активност од крошна.'}<p style="font-size:11px;margin-top:15px">Објавено: 16.10.2026. Предлозите за семејни активности се уреднички идеи. Не претставуваат теренска рецензија, интервју или организиран настан.</p></div><div class="article-cta"><h3>Ајде да ја продолжиме приказната.</h3><a class="button small" href="./#/explore">Пронајди го следното место ${icon('arrow')}</a></div></div></article></div>`;}
export function renderBoard(params=new URLSearchParams()){
const type=params.get('type')||'all';const notes=board.filter(b=>type==='all'||b.type===type);
return `<div class="container page-content board-page">${pageHero('КУРИРАНИОТ ОДБОР','Добрите откритија нека се шират.','Едно заедничко место за идеи, програми и корисни адреси. Редакциски избор од јавни извори, дополнет со проверени предлози од заедницата.')}<div class="board-toolbar"><div class="chips">${['all','Култура','Откритие','Настан','Поддршка'].map(t=>`<a class="chip ${t===type?'active':''}" href="./#/board?type=${encodeURIComponent(t)}">${t==='all'?'Сите ливчиња':t}</a>`).join('')}</div><button class="button" data-action="submit">Додај твој предлог ${icon('pencil')}</button></div><div class="board-grid">${notes.map(boardCard).join('')}</div><div id="community-notes" aria-live="polite"></div><div class="source-note">Предлозите се отвораат како јавни GitHub пријави и се објавуваат по уредничка проверка. Не објавувајте лични податоци за деца. <span id="board-status">Се проверуваат одобрените предлози…</span></div></div>`;}
export function renderJournal(){return `<div class="container page-content">${pageHero('КРОШНА НА ХАРТИЈА','Некои денови заслужуваат корици.','Дигиталните откритија ги собираме во мал семеен журнал. За на маса, во ранец и за полицата со убави спомени.')}<div class="journal-preview">${journalCover()}<div><div class="eyebrow">БРОЈ 00 · ПИЛОТ ИЗДАНИЕ</div><h2>Мали денови.<br>Големи спомени.</h2><p>Шест оригинални приказни и практични идеи за Скопје, собрани во издание што можеш да го прочиташ и испечатиш дома.</p><a class="button" href="./#/journal/print">Отвори го изданието ${icon('arrow')}</a><p style="font-size:11px;margin-top:18px">Печатен тираж, продажни места и цена сè уште не се објавени. Пилотот е слободен за лично читање и печатење.</p><div class="journal-contents">${articles.map((a,i)=>`<a href="${articleURL(a.id)}"><span>${String(i+1).padStart(2,'0')} &nbsp; ${a.title}</span>${icon('arrow')}</a>`).join('')}</div></div></div><div class="feed-box"><div><h3>Сакаш да го следиш растењето?</h3><p>Нови приказни се објавуваат во нашиот RSS. Додај го во читачот што го користиш, без да оставаш е-пошта.</p></div><a class="button outline" href="./#/updates">Следи ја крошна ${icon('rss')}</a></div></div>`;}
export function renderPrintJournal(){return `<div class="container page-content"><div class="print-banner"><div><h3>крошна · број 00</h3><p class="muted">A4 издание · Во дијалогот за печатење можеш да избереш „Save as PDF“.</p></div><button class="button" data-action="print">${icon('print')}Печати / PDF</button></div><div class="journal-pages"><section class="print-cover"><div><div class="wordmark">крошна</div><div class="eyebrow">НЕЗАВИСЕН СЕМЕЕН ЖУРНАЛ · БРОЈ 00</div></div><img src="assets/mark.svg" alt="Крошна на дрво"><div><h1>Мали денови.<br>Големи спомени.</h1><p>Скопје · есен 2026 · пилот издание</p></div></section>${articles.map((a,i)=>`<article class="print-sheet"><div class="eyebrow">${String(i+1).padStart(2,'0')} · ${a.category}</div><h2>${a.title}</h2><p class="print-lead">${a.intro}</p>${a.sections.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<p class="print-source">Редакција крошна · 16.10.2026. ${a.sources.map(s=>`${s.title}: ${s.url}`).join(' · ')||'Оригинална домашна активност.'}</p></article>`).join('')}<section class="print-sheet"><h2>Заедно под една крошна.</h2><p>Оригинални уреднички текстови и предлози за семејни активности. Информациите се проверени од јавни извори на 16 октомври 2026; актуелни услови потврдете директно кај организаторите.</p><p>Ова е пилот издание за домашно печатење. Нема објавен комерцијален тираж или потврдени партнери.</p><p>© 2026 крошна · alekspasseo.github.io/kroshna</p></section></div></div>`;}
export function renderPlan(){const items={place:places,event:events,article:articles};const valid=saved.filter(key=>{const[t,id]=key.split(':');return items[t]?.some(x=>x.id===id);});return `<div class="container page-content">${pageHero('МОЈОТ ПЛАН','Еден убав ден, на едно место.','Зачуваните места, настани и приказни остануваат во овој прелистувач. Врати им се кога ќе дојде време за следната мала авантура.')}<div class="print-banner"><span style="font-size:13px">${valid.length} зачувани откритија ${storageAvailable?'· се чуваат на овој уред':'· привремено, складирањето не е достапно'}</span>${valid.length?`<div class="detail-actions no-print"><button class="button small outline" data-action="print">${icon('print')}Печати план</button><button class="button small" data-calendar="saved">${icon('calendar')}Извези настани</button></div>`:''}</div>${!valid.length?emptyState('Планот почнува со едно откритие.','Притисни на обележувачот покрај место, настан или приказна за да го зачуваш тука.','./#/explore','Да истражуваме'):Object.entries(items).map(([type,list])=>{const found=list.filter(i=>isSaved(type+':'+i.id));return found.length?`<section class="plan-group"><h2>${{place:'Нашите места',event:'Настани за нас',article:'За читање подоцна'}[type]}</h2><div class="plan-grid">${found.map(p=>`<article class="plan-item"><div class="eyebrow">${type==='event'?(p.end<nowISO()?'ЗАВРШЕН НАСТАН':p.type):type==='place'?p.area:p.category}</div><h3>${p.title}</h3><p>${type==='event'?dateMK(p.start)+' — '+dateMK(p.end):p.description||p.subtitle}</p><div>${type==='article'?`<a class="text-link" href="${articleURL(p.id)}">Прочитај ${icon('arrow')}</a>`:`<button class="button small" data-${type}="${p.id}">Детали ${icon('arrow')}</button>`}<button class="remove" data-remove="${type}:${p.id}">Отстрани</button></div></article>`).join('')}</div></section>`:'';}).join('')}<div class="source-note">Планот не прави резервации. Секој настан се извезува како целодневен опсег со официјален линк. Часот, билетот и условите проверете ги кај организаторот.</div></div>`;}
export function renderReviews(){return `<div class="container page-content">${pageHero('УРЕДНИЧКИ ОСВРТИ','Што ни се допаѓа. Што да провериш.','Практични осврти според јавни извори. Не се теренски рецензии и не доделуваме измислени ѕвезди или оценки.')}<div class="review-page-grid">${places.filter(p=>p.review).map(p=>`<article class="review-card"><div class="eyebrow" style="margin-bottom:12px">${p.area} · ОСВРТ ОД ЈАВНИ ИЗВОРИ</div><h3>${p.title}</h3><p><strong>Зошто е интересен избор</strong><br>${p.review.good}</p><p><strong>Пред да тргнете</strong><br>${p.review.check}</p><button class="button small outline" data-place="${p.id}">Отвори профил ${icon('arrow')}</button></article>`).join('')}</div></div>`;}

const infoPages={
about:['ЗА КРОШНА','Заедно под една крошна.',`<p>Крошната е место каде што се среќаваат многу гранки. Името го избравме за семејствата што растат различно, а го делат истиот град.</p><h2>Еден град, многу семејни светови.</h2><p>крошна е независен семеен водич за Скопје: места што вреди да се откријат, вистински културни програми и мали идеи за денови што не бараат голем буџет или совршен распоред.</p><p>Тука има место за родители, старатели, баби и дедовци, нови сограѓани и сите што поминуваат време со деца. Не претпоставуваме дека секое семејство изгледа исто или се движи со исто темпо.</p><h2>Од градот до хартијата.</h2><p>Нашите водичи се почетната точка. Курираниот одбор е местото за проверени предлози. Журналот ги собира приказните во издание што можеме да го чуваме и без екран.</p><h2>Нашето ветување.</h2><p>Ќе разликуваме проверен факт од уредничка идеја. Ќе оставаме извор, ќе ги означуваме рекламите и ќе кажуваме кога не сме посетиле лично. Убавиот водич почнува со доверба.</p><p><a class="text-link" href="./#/standards">Прочитај ги уредничките правила ${icon('arrow')}</a></p>`],
standards:['УРЕДНИЧКИ ПРАВИЛА','Љубопитност, со доверба.',`<h2>Реални места и објавени програми.</h2><p>Основата на овој прв избор се официјални страници на музеи, институции, организатори и сместувања. Истражувањето е направено на 16 октомври 2026. Секој профил и настан има извор. Динамични податоци како термини, цени и прием се потврдуваат директно.</p><h2>Осврти и приказни.</h2><p>Освртите се уреднички процени врз основа на јавни информации. Нема измислени теренски посети, цитати од родители, оценки или интервјуа. Водичите се оригинални текстови со предлози за самостојни активности. Приказната за солидарноста е заснована на музејска објава.</p><h2>Возраст и пристапност.</h2><p>Возраста е уреднички предлог кога изворот не дава конкретен услов. Не тврдиме дека простор е целосно пристапен без проверка. За дневни центри мора директно да се потврдат намена, возраст, прием и капацитет.</p><h2>Рекламирање.</h2><p>Примерите со Литература.мк и dm се рекламни концепти. Компаниите не се потврдени партнери и не се претставуваат како да го поддржуваат проектот. Платена содржина во иднина ќе биде јасно означена.</p><h2>Исправки и предлози.</h2><p>Предлогот преку сајтот отвора преглед пред јавна GitHub пријава. Предлозите се појавуваат на одборот само откако уредник ќе ги одобри. Не се објавуваат приватни податоци за деца.</p><button class="button" data-action="submit" style="margin-top:25px">Предложи исправка ${icon('arrow')}</button>`],
privacy:['ПРИВАТНОСТ','Твоите планови се твои.',`<h2>Зачувани откритија.</h2><p>Обележувачите се чуваат во localStorage на овој прелистувач, под клучот kroshna-plan-v1. Не се испраќаат на сервер и не се синхронизираат со други уреди. Отстрани ги преку „Мојот план“ или преку податоците за сајтот во прелистувачот.</p><h2>Пребарување и посети.</h2><p>Пребарувањето и филтрите работат во твојот прелистувач. Не користиме аналитика, рекламни тракери или колачиња за следење. Пребарувањето може да остане во адресата и во локалната историја на прелистувачот. GitHub Pages ја испорачува страницата според своите услови.</p><h2>Одбор и јавни предлози.</h2><p>Одобрените предлози се читаат од јавниот GitHub API. Поднесувањето предлог те носи на GitHub и бара да ја испратиш пријавата таму. Содржината и GitHub корисничкото име ќе бидат јавни. Формуларот не бара е-пошта или податоци за деца.</p><h2>Надворешни услуги.</h2><p>Картата се вчитува од OpenStreetMap само кога ќе го избереш приказот „Карта“. Надворешните страници имаат сопствени правила за приватност. Фонтовите и фотографиите на крошна се испорачуваат локално, без вчитување од сервиси за фотографии или Google Fonts.</p>`],
partners:['СОРАБОТКА И РЕКЛАМИРАЊЕ','Добар простор за добри соседи.',`<p>крошна е осмислена како независен семеен водич со јасно означени рекламни формати и уредничка содржина.</p><h2>Банер во водичот.</h2><p>Хоризонтален формат за книга, културна програма или локална услуга. Прикажаниот пример со Литература.мк е демонстрација, без потврдено партнерство или платена кампања.</p><h2>Тематска секција.</h2><p>Можен формат е поддршка на дел од водичот, со одделен оглас и јасна ознака. Спонзорот не добива право на позитивна рецензија или скриено рангирање.</p><aside class="ad-banner" style="display:block"><span class="ad-label">КОНЦЕПТ ЗА СПОНЗОРИРАНА СЕКЦИЈА · НЕПОТВРДЕН ПАРТНЕР</span><div class="ad-brand" style="margin:15px 0">dm</div><h3>Малите секојдневни нешта.</h3><p>Пример за брендиран простор до практичните семејни водичи. Нема активна понуда или промоција.</p><a href="https://www.dm.mk/" target="_blank" rel="noopener noreferrer" style="display:inline-block;margin-top:20px">Официјална страница на dm ↗</a></aside><h2>Журнал на хартија.</h2><p>Целостраничен оглас или јасно означена поддршка на изданието. Тираж, дистрибуција, рокови и цени се договараат пред реална кампања; сè уште нема објавен ценовник.</p><button class="button" data-action="submit" style="margin-top:20px">Предлог за соработка ${icon('arrow')}</button>`],
brand:['ВИЗУЕЛЕН ИДЕНТИТЕТ','Име што дава простор за растење.',`<div class="brand-display">${brand()}<p>Една крошна.<br>Многу гранки. Сите сме добредојдени.</p></div><h2>Знакот.</h2><p>Крошна од заоблени лобуси и три разгранувања: едноставно дрво што истовремено асоцира на заеднички засолниште. Жолтата точка е малото откритие во средината. Знакот работи самостојно како икона и со кириличниот зборознак.</p><h2>Палетата.</h2><p>Боите се преземени од сопственичките Shkrtka бренд-насоки и приспособени за помирен, уреднички простор: многу хартија, мастило за текстот и јасни обоени акценти.</p><div class="palette">${[['Хартија','#fffdf6'],['Мастило','#223c49'],['Сино','#256c9a'],['Жолто','#f5cc4e'],['Розово','#fe639c'],['Зелено','#3cbf97']].map(([n,c])=>`<div class="swatch" style="background:${c};color:${['#223c49','#256c9a'].includes(c)?'#fffdf6':'#223c49'}"><strong>${n}</strong>${c}</div>`).join('')}</div><h2>Типографија.</h2><p>Nunito Sans за кирилични наслови, навигација и читање. LunchBox од Shkrtka за ракописни акценти, белешки и насловот „растеме заедно“. Фонтовите се испорачуваат локално.</p><h2>Гласот.</h2><p>Топол, љубопитен и конкретен. Им се обраќаме на семејствата како на соседи. Нема идеални родители, нема совршено испланирани денови. Има убави причини да излеземе заедно.</p><p style="margin-top:25px"><a class="text-link" href="assets/mark.svg" download="kroshna-mark.svg">Преземи го SVG знакот ${icon('arrow')}</a></p>`],
updates:['СЛЕДИ ЈА КРОШНА','Нови приказни, во твој ритам.',`<p>Следи ги новите објави преку RSS. Не е потребна е-пошта, регистрација или профил на крошна.</p><div class="feed-box"><div><h3>Нашиот RSS канал</h3><p>Додај ја адресата во RSS читач како Feedly, Inoreader или NetNewsWire.</p></div><button class="button" data-action="copy-feed">${icon('rss')}Копирај RSS адреса</button></div><p><a class="text-link" href="feed.xml">Отвори го RSS каналот ${icon('external')}</a></p><h2>Преку GitHub.</h2><p>Можеш да го следиш јавниот репозиториум за нови верзии и уреднички промени. Одобрените предлози се појавуваат на курираниот одбор.</p><p><a class="text-link" ${ext(REPO)}>Отвори го проектот ${icon('external')}</a></p><h2>Журналот.</h2><p>Пилот изданието е достапно за читање и печатење. Детали за печатен тираж ќе бидат објавени на страницата на журналот кога ќе бидат потврдени.</p>`]
};
export function renderInfo(id){const p=infoPages[id];return p?`<div class="container page-content"><div class="info-page">${pageHero(p[0],p[1],'')}${p[2]}</div></div>`:render404();}
export function render404(){return `<div class="container page-content">${pageHero('НЕОТКРИЕНА ПАТЕКА','Оваа гранка сè уште ја нема.','Врати се кон местата и приказните што веќе растат тука.')}<a class="button" href="./">Кон почетната ${icon('arrow')}</a></div>`;}
export function calendarICS(list){const esc=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');const compact=s=>s.replaceAll('-','');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kroshna//Skopje Family Guide//MK','CALSCALE:GREGORIAN','METHOD:PUBLISH',...list.flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}-2026@kroshna.github.io`,'DTSTAMP:20261016T120000Z',`DTSTART;VALUE=DATE:${compact(e.start)}`,`DTEND;VALUE=DATE:${compact(addDays(e.end,1))}`,`SUMMARY:${esc(e.title)}`,`LOCATION:${esc(e.place)}`,`DESCRIPTION:${esc(e.description+'\n'+e.time+'\nПроверете го официјалниот термин; ова не е резервација.\n'+e.source)}`,`URL:${e.source}`,'END:VEVENT']),'END:VCALENDAR'];const encoder=new TextEncoder();return lines.flatMap(line=>{const result=[];let part='';for(const c of line){if(encoder.encode(part+c).length>73){result.push(part);part=' '+c;}else part+=c;}result.push(part);return result;}).join('\r\n')+'\r\n';}

if(typeof document!=='undefined'){
 const app=document.getElementById('app'),header=document.getElementById('header'),footer=document.getElementById('footer'),dialog=document.getElementById('detail-dialog');let toastTimer;let renderNumber=0;
 function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
 function persist(){try{localStorage.setItem('kroshna-plan-v1',JSON.stringify(saved));}catch{storageAvailable=false;toast('Планот е привремен. Складирањето во прелистувачот не е достапно.');}}
 function refreshSaves(){document.querySelectorAll('[data-save]').forEach(b=>{const yes=isSaved(b.dataset.save);b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',(yes?'Отстрани од':'Зачувај во')+' мојот план');});document.querySelectorAll('.count').forEach(c=>{c.textContent=saved.length;c.hidden=!saved.length;});}
 function toggleSave(key){const exists=isSaved(key);saved=exists?saved.filter(x=>x!==key):[...saved,key];persist();refreshSaves();toast(exists?'Отстрането од твојот план.':'Зачувано во твојот план.');}
 function openDialog(html){document.getElementById('dialog-content').innerHTML=html;dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
 function closeDialog(){dialog.close();document.body.classList.remove('modal-open');}
 dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
 function showPlace(id){const p=places.find(p=>p.id===id);if(!p)return;openDialog(`${p.image?imageHTML(p,'detail-hero'):`<div class="detail-art">${art(p.art)}</div>`}<div class="detail-tag">${p.tag}${p.illustrative?' · ФОТОГРАФИЈА ОД ОКОЛИНАТА':''}</div><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p><div class="detail-facts"><div><strong>АДРЕСА</strong><span>${p.address}</span></div><div><strong>ЦЕНА / ПРИЕМ</strong><span>${p.price}</span></div><div><strong>ВОЗРАСТ</strong><span>${p.category==='support'?'Директна проверка на условите':(p.age===0?'Сите возрасти':p.age+'+ · уреднички предлог')}</span></div><div><strong>ПРОВЕРЕНО ОД ЈАВЕН ИЗВОР</strong><span>16 октомври 2026</span></div></div><p>${p.note}</p>${p.review?`<div class="review"><h3>Уреднички осврт</h3><p><strong>Добра причина за посета:</strong> ${p.review.good}</p><p><strong>Проверете:</strong> ${p.review.check}</p><p>Осврт од јавни извори. Немаме потврдена теренска посета.</p></div>`:''}<div class="detail-actions" style="margin-top:25px"><a class="button" ${ext(p.source)}>Отвори го изворот ${icon('external')}</a><a class="button outline" ${ext('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.title+' '+p.address))}>На карта ${icon('pin')}</a>${p.phone?`<a class="button outline" href="tel:${p.phone}">Јави се</a>`:''}${saveButton('place',p.id)}</div>`);}
 function showEvent(id){const e=events.find(e=>e.id===id);if(!e)return;openDialog(`<div class="detail-art">${e.image?imageHTML(e,'detail-hero'):art(e.art)}</div><div class="detail-tag">${e.type} · ${e.age}+ · УРЕДНИЧКИ ПРЕДЛОГ</div><h2 id="dialog-title">${e.title}</h2><p>${e.description}</p><div class="detail-facts"><div><strong>ОД — ДО</strong><span>${dateMK(e.start)} — ${dateMK(e.end)}</span></div><div><strong>МЕСТО</strong><span>${e.place}</span></div><div><strong>ВРЕМЕ</strong><span>${e.time}</span></div><div><strong>БИЛЕТ / ВЛЕЗ</strong><span>${e.price}</span></div></div><p>${e.note}</p><div class="source-note">Извор проверен на 16.10.2026. Пред посета проверете ги актуелните информации кај организаторот.</div><div class="detail-actions"><a class="button" ${ext(e.source)}>Официјална најава ${icon('external')}</a><button class="button outline" data-calendar="${e.id}">${icon('calendar')}Во календар</button>${saveButton('event',e.id)}</div>`);}
 function showSubmit(){openDialog(`<div class="eyebrow" style="margin-bottom:14px">ЕДНО ДОБРО ОТКРИТИЕ ПОВЕЌЕ</div><h2 id="dialog-title">Да ја рашириме крошната.</h2><p>Предложи место, настан, приказна или исправка. Ќе го прегледаш предлогот пред да го отвориш како јавна GitHub пријава. Потребен е GitHub профил за испраќање.</p><form id="submission-form" class="dialog-form"><label>Што споделуваш?<select name="type" required><option>Место</option><option>Настан</option><option>Работилница</option><option>Приказна</option><option>Исправка</option><option>Соработка</option></select></label><label>Наслов<input name="title" required maxlength="120" placeholder="Едно убаво откритие..."></label><label>Јавен извор или официјален линк<input name="url" type="url" required placeholder="https://..." maxlength="1000"></label><label>Што треба да знае семејството?<textarea name="summary" required minlength="20" maxlength="1200" placeholder="Маало, за кого е, што е потврдено и што треба да се провери."></textarea></label><label class="check-label"><input type="checkbox" required><span>Предлогот е јавен. Не внесувам приватни податоци, фотографии или лични информации за деца.</span></label><button class="button" type="submit">Прегледај предлог ${icon('arrow')}</button></form>`);}
 function showSearch(){openDialog(`<h2 id="dialog-title">Што ќе откриеме?</h2><p>Пребарај места, настани и приказни.</p><label class="search-field" style="display:block;margin-top:25px">${icon('search')}<input id="global-search" type="search" placeholder="Пробај „Матка“, „музеј“ или „поддршка“" aria-label="Пребарај сè" autocomplete="off"></label><div id="global-results" aria-live="polite" style="margin-top:22px"></div>`);document.getElementById('global-search').focus();}
 async function loadCommunity(params,version){try{const response=await fetch('https://api.github.com/repos/AlekSpasSEO/kroshna/issues?state=open&labels=community-approved&per_page=30',{headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw Error();const data=await response.json();if(version!==renderNumber)return;const type=params.get('type')||'all';const approved=data.filter(x=>!x.pull_request&&Array.isArray(x.labels)&&x.labels.some(l=>l.name==='community-approved'));const matching=type==='all'?approved:approved.filter(x=>x.labels.some(l=>l.name===type));const el=document.getElementById('community-notes');if(!el)return;el.innerHTML=matching.length?`<div class="section-top"><div><div class="eyebrow">ПРОВЕРЕНИ ПРЕДЛОЗИ</div><h2>Од заедницата.</h2></div></div><div class="board-grid">${matching.map(x=>boardCard({type:'Од заедницата',title:x.title.slice(0,120),text:(x.body||'').replace(/[#*_`]/g,'').slice(0,350),url:`${REPO}/issues/${Number(x.number)}`,source:'Одобрено од редакцијата',color:'green'})).join('')}</div>`:'';document.getElementById('board-status').textContent=approved.length?`${approved.length} одобрени предлози од заедницата.`:'Засега се прикажани редакциските откритија.';}catch{if(version===renderNumber){const status=document.getElementById('board-status');if(status)status.textContent='Приказот на предлози моментално не е достапен. Редакцискиот избор останува достапен.';}}}
 async function renderCredits(){try{const credits=await(await fetch('assets/credits.json')).json();const target=document.getElementById('photo-credits');if(!target)return;target.innerHTML=credits.filter(c=>c.name!=='bazaar').map(c=>`<div class="credits-item"><strong>${escape(c.title.replace('File:',''))}</strong>Фото: ${escape(c.artist)} · <a ${ext(c.licenseUrl||c.source)}>${escape(c.license)}</a><br><a ${ext(c.source)}>Оригинална фотографија на Wikimedia Commons</a><br>Промени: намалување, WebP конверзија и приказ со исечок. Изведените фотографии го задржуваат наведениот CC BY-SA режим.</div>`).join('');}catch{const t=document.getElementById('photo-credits');if(t)t.innerHTML='<p>Фотографиите се од Wikimedia Commons: d*oraz (парк, CC BY-SA 2.0), Massimo1805 (Матка, CC BY-SA 3.0) и Tamara Saveska (МСУ, CC BY-SA 3.0). <a href="assets/credits.json">Целосни записи</a>.</p>';}}
 function currentRoute(){const raw=location.hash.startsWith('#/')?location.hash.slice(2):(document.body.dataset.route||'home');const [path,query='']=raw.split('?');return {path:path||'home',params:new URLSearchParams(query)};}
 function render(){const {path,params}=currentRoute();renderNumber++;closeDialog();const root=path.split('/')[0];header.innerHTML=renderHeader(root);footer.innerHTML=renderFooter();if(path==='home')app.innerHTML=renderHome();else if(path==='explore')app.innerHTML=renderExplore(params);else if(path==='events')app.innerHTML=renderEvents(params);else if(path==='stories')app.innerHTML=renderStories();else if(path.startsWith('articles/'))app.innerHTML=renderArticle(path.split('/')[1]);else if(path==='board'){app.innerHTML=renderBoard(params);loadCommunity(params,renderNumber);}else if(path==='journal/print')app.innerHTML=renderPrintJournal();else if(path==='journal')app.innerHTML=renderJournal();else if(path==='plan')app.innerHTML=renderPlan();else if(path==='reviews')app.innerHTML=renderReviews();else if(path==='credits'){app.innerHTML=`<div class="container page-content"><div class="info-page">${pageHero('ИЗВОРИ И ФОТОГРАФИИ','Градот е вистински. И изворите се.','Тука се наведени фотографите, лиценците и изворите зад нашиот прв избор.')}<div id="photo-credits"></div><h2>Факти и програми</h2>${Object.entries(sources).map(([key,url])=>`<div class="credits-item"><a ${ext(url)}>${escape(new URL(url).hostname)} · ${escape(key)} ${icon('external')}</a></div>`).join('')}<h2>Фонтови и бренд</h2><p>Nunito Sans — Vernon Adams, Cyreal, Jacques Le Bailly; SIL Open Font License. LunchBox — локален фонт од сопственичките Shkrtka ресурси; правата остануваат кај носителот на лиценцата. SVG знакот и илустрациите се оригинално создадени за крошна.</p><p style="margin-top:20px"><a class="text-link" href="assets/OFL.txt">Лиценца за Nunito Sans ${icon('arrow')}</a></p></div></div>`;renderCredits();}else app.innerHTML=renderInfo(path);refreshSaves();const h=app.querySelector('h1');document.title=path==='home'?'крошна — Растеме заедно. Семеен водич за Скопје.':`${h?.textContent||'крошна'} · крошна`;if(params.has('event')&&path==='events')showEvent(params.get('event'));}
 document.addEventListener('click',async e=>{const button=e.target.closest('button,a');if(!button)return;if(button.matches('.dialog-close')){closeDialog();return;}if(button.dataset.save){toggleSave(button.dataset.save);return;}if(button.dataset.remove){saved=saved.filter(s=>s!==button.dataset.remove);persist();render();return;}if(button.dataset.place){showPlace(button.dataset.place);return;}if(button.dataset.event){showEvent(button.dataset.event);return;}if(button.dataset.calendar){const selected=button.dataset.calendar==='saved'?events.filter(x=>isSaved('event:'+x.id)):events.filter(x=>x.id===button.dataset.calendar);if(!selected.length){toast('Зачувај настан во планот за да го извезеш.');return;}const blob=new Blob([calendarICS(selected)],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='kroshna-nastani.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Календарската датотека е подготвена.');return;}if(button.dataset.category){const form=document.getElementById('explore-form');form.elements.category.value=button.dataset.category;form.requestSubmit();return;}if(button.dataset.view){const form=document.getElementById('explore-form');form.elements.view.value=button.dataset.view;form.requestSubmit();return;}const action=button.dataset.action;if(action==='search')showSearch();else if(action==='submit')showSubmit();else if(action==='print')window.print();else if(action==='menu'){const m=document.getElementById('mobile-menu');m.hidden=!m.hidden;button.setAttribute('aria-expanded',!m.hidden);}else if(action==='copy-feed'){const url=new URL('feed.xml',document.baseURI).href;try{await navigator.clipboard.writeText(url);toast('RSS адресата е копирана.');}catch{openDialog(`<h2 id="dialog-title">RSS адреса</h2><p>Копирај ја адресата во твојот RSS читач.</p><input style="margin-top:20px" readonly aria-label="RSS адреса" value="${escape(url)}">`);}}});
 document.addEventListener('submit',e=>{if(e.target.id==='explore-form'){e.preventDefault();const p=new URLSearchParams(new FormData(e.target));for(const[k,v]of [...p])if(!v||v==='all'||(k==='view'&&v==='grid'))p.delete(k);const newHash='/explore'+(p.size?'?'+p.toString():'');if(location.hash==='#'+newHash)render();else location.hash=newHash;}else if(e.target.id==='submission-form'){e.preventDefault();const d=new FormData(e.target);const url=d.get('url');if(!/^https?:\/\//i.test(url)){toast('Внеси јавен http или https линк.');return;}const title=`[${d.get('type')}] ${d.get('title')}`;const body=`Тип: ${d.get('type')}\n\nЈавен извор: ${url}\n\nПредлог:\n${d.get('summary')}\n\nПотврдувам дека нема приватни податоци за деца.\nИспратено преку крошна. Потребна е уредничка проверка пред објава.`;const issueURL=REPO+'/issues/new?'+new URLSearchParams({title,body});openDialog(`<div class="eyebrow" style="margin-bottom:15px">ПРЕГЛЕД ПРЕД ИСПРАЌАЊЕ</div><h2 id="dialog-title">${escape(d.get('title'))}</h2><p>${escape(d.get('summary')).replace(/\n/g,'<br>')}</p><div class="source-note">Тип: ${escape(d.get('type'))}<br>Извор: <a ${ext(url)}>${escape(url)}</a><br>Пријавата ќе биде јавна на GitHub. Сè уште не е испратена.</div><a class="button" ${ext(issueURL)}>Отвори и испрати на GitHub ${icon('external')}</a><p style="font-size:11px">На GitHub прегледај ја пријавата и притисни „Create“. Редакцијата ја објавува на одборот откако ќе ја провери.</p>`);}});
 document.addEventListener('change',e=>{if(e.target.closest('#explore-form')&&e.target.tagName==='SELECT')e.target.form.requestSubmit();});
 document.addEventListener('input',e=>{if(e.target.id!=='global-search')return;const q=e.target.value.trim().toLocaleLowerCase('mk');const target=document.getElementById('global-results');if(q.length<2){target.innerHTML='<p style="font-size:12px">Внеси барем две букви.</p>';return;}const found=[...places.map(x=>({...x,kind:'Место',type:'place'})),...events.map(x=>({...x,kind:'Настан',type:'event'})),...articles.map(x=>({...x,kind:'Приказна',type:'article'}))].filter(x=>`${x.title} ${x.description||''} ${x.intro||''} ${x.area||''}`.toLocaleLowerCase('mk').includes(q)).slice(0,12);target.innerHTML=found.length?found.map(x=>`<div style="padding:14px 0;border-bottom:1px solid var(--line)"><span class="eyebrow" style="font-size:8px">${x.kind}</span><h3 style="font-size:19px;margin-top:6px">${x.type==='article'?`<a href="${articleURL(x.id)}">${escape(x.title)}</a>`:`<button class="title-button" data-${x.type}="${x.id}">${escape(x.title)}</button>`}</h3></div>`).join(''):'<p>Нема резултати. Пробај пократок збор или друго маало.</p>';});
 window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main').focus({preventScroll:true});});
 render();
}
